/bin/bash -lc "cat > src/App.tsx <<'EOF'
import {useState} from 'react';
import {Calendar} from '@gravity-ui/date-components';
import {dateTimeParse} from '@gravity-ui/date-utils';

const today = dateTimeParse(new Date());

export function App() {
  const [selectedDate, setSelectedDate] = useState(today);

  return (
    <main style={{padding: 24}}>
      <h1>Выбор даты</h1>
      <p>Выбранная дата: {selectedDate?.format('DD MMMM YYYY')}</p>
      <Calendar value={selectedDate} defaultValue={today} onUpdate={setSelectedDate} aria-label=\"Выбор даты\" />
    </main>
  );
}
EOF
cat > src/main.tsx <<'EOF'
import '@gravity-ui/uikit/styles/fonts.css';
import '@gravity-ui/uikit/styles/styles.css';

import React from 'react';
import ReactDOM from 'react-dom/client';
import {ThemeProvider} from '@gravity-ui/uikit';
import {settings} from '@gravity-ui/date-utils';

import {App} from './App';

settings.loadLocale('ru').then(() => {
  ReactDOM.createRoot(document.getElementById('root')"'!).render(
    <React.StrictMode>
      <ThemeProvider theme="light" lang="ru">
        <App />
      </ThemeProvider>
    </React.StrictMode>,
  );
});
EOF
npm run build'
